async function analyze(){if((!message.trim()&&!imageFile)||busy)return;setBusy(true);setAnalysis(null);setAiError('');try{const result=await analyzeMessage({message,imageFile,language:analysisLanguage});setAnalysis(result)}catch(error){const reason=String(error?.message||'');const lower=reason.toLowerCase();const isOutOfScope=lower.includes("doesn't look relevant to scam checking")||lower.includes("not relevant to scam checking")||reason.includes("স্ক্যাম চেকিংয়ের জন্য প্রাসঙ্গিক");if(isOutOfScope){setAnalysis({isRelevant:false,responseLanguage:analysisLanguage,verdict:"out_of_scope",summary_bn:"আপনার দেওয়া কনটেন্টটি স্ক্যাম-সম্পর্কিত বার্তা বা যোগাযোগ হিসেবে শনাক্ত হয়নি। তাই ভুল ঝুঁকি-স্কোর বা প্রতারণার verdict না দিয়ে এই ইনপুটের স্ক্যাম বিশ্লেষণ করা হয়নি।",summary_en:"The submitted content was not identified as a scam-related message or interaction. To avoid a misleading risk score or fraud verdict, no scam assessment was made.",guidance_bn:"কোনো SMS, WhatsApp বা Messenger বার্তা, ইমেইল, চাকরি বা পুরস্কারের অফার, পেমেন্ট অনুরোধ, অ্যাকাউন্ট সতর্কতা অথবা সন্দেহজনক লিংক-সহ স্ক্রিনশট দিলে SHONKET AI সেটি পরীক্ষা করতে পারবে।",guidance_en:"Try a text or screenshot of an SMS, WhatsApp or Messenger message, email, job or prize offer, payment request, account alert, or a message containing a suspicious link.",confidence:"low",engine:"Gemini"});}else{setAiError(reason||'Analysis failed. Please try again.')}}finally{setBusy(false)}}
function startVoice(){setVoiceError('');const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){setVoiceError(t('Voice input is not supported in this browser. Try Chrome.','এই ব্রাউজারে ভয়েস ইনপুট সমর্থিত নয়। Chrome ব্যবহার করুন।'));return}const recognition=new SpeechRecognition();recognition.lang=voiceInputLanguage==='bn'?'bn-BD':'en-US';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>setVoiceListening(true);recognition.onerror=()=>{setVoiceListening(false);setVoiceError(t('Could not capture speech. Check microphone permission and try again.','কথা রেকর্ড করা যায়নি। মাইক্রোফোনের অনুমতি পরীক্ষা করে আবার চেষ্টা করুন।'))};recognition.onend=()=>setVoiceListening(false);recognition.onresult=e=>{const transcript=e.results?.[0]?.[0]?.transcript||'';setMessage(v=>v? v+' '+transcript:transcript);setAnalysis(null)};try{recognition.start()}catch{setVoiceListening(false);setVoiceError(t('Microphone is already active.','মাইক্রোফোন ইতিমধ্যে চালু আছে।'))}}
function speakAnalysis(){if(!analysis)return;if(!('speechSynthesis'in window)){setVoiceError(t('Text-to-speech is not supported in this browser.','এই ব্রাউজারে লেখা পড়ে শোনানোর সুবিধা নেই।'));return}window.speechSynthesis.cancel();const textToRead=[resultLanguage==='bn'?analysis.summary_bn:analysis.summary_en,...(analysis.evidence||[]).map(e=>resultLanguage==='bn'?e.reason_bn:e.reason_en),...(analysis.safe_actions||[]),analysis.uncertainty].filter(Boolean).join('. ');const utterance=new SpeechSynthesisUtterance(textToRead);utterance.lang=resultLanguage==='bn'?'bn-BD':'en-US';const chosen=voiceOptions.find(v=>v.name===selectedVoice);if(chosen)utterance.voice=chosen;utterance.onstart=()=>{setSpeaking(true);setSpeechPaused(false)};utterance.onend=()=>{setSpeaking(false);setSpeechPaused(false)};utterance.onerror=()=>{setSpeaking(false);setSpeechPaused(false)};window.speechSynthesis.speak(utterance)}
function pauseResumeSpeech(){if(!('speechSynthesis'in window))return;if(window.speechSynthesis.paused){window.speechSynthesis.resume();setSpeechPaused(false)}else{window.speechSynthesis.pause();setSpeechPaused(true)}}
