function handleImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setAiError('Upload a PNG, JPG or WebP screenshot.');return}if(file.size>3*1024*1024){setAiError('Screenshot must be 3 MB or smaller.');return}setImageFile(file);setImagePreview(URL.createObjectURL(file));setAnalysis(null);setAiError('')}
function removeImage(){setImageFile(null);setImagePreview('');const input=document.getElementById('screenshot-upload');if(input)input.value=''}
